// dist/handlers/dashboard_html.js
import assert25 from "node:assert";
function injectSseScript(endpoint) {
  assert25(typeof endpoint === "string" && endpoint.startsWith("/"), "injectSseScript: endpoint must be root-relative");
  const html = `<script>
(function () {
  var es = new EventSource('${endpoint}');
  es.addEventListener('stats', function (e) {
    var data;
    try { data = JSON.parse(e.data); } catch { return; }
    if (!data || typeof data !== 'object') return;
    var bc = document.getElementById('blocked-count');
    var cs = document.getElementById('connection-status');
    if (bc) {
      var n = typeof data.blockedCount === 'number' ? data.blockedCount : 0;
      bc.textContent = n > 0 ? n + ' FLAG' + (n > 1 ? 'S' : '') : 'CLEAR';
      bc.style.color = n > 0 ? 'var(--red)' : 'var(--dim)';
    }
    if (cs) { cs.textContent = '\xB7 LIVE'; cs.className = 'live'; }
  });
  es.addEventListener('error', function (e) {
    var data;
    try { data = JSON.parse(e.data); } catch { data = null; }
    var cs = document.getElementById('connection-status');
    if (!cs) return;
    cs.textContent = data && data.message ? '\xB7 ' + data.message : '\xB7 vault error';
    cs.className = 'error';
  });
  es.onerror = function () {
    var cs = document.getElementById('connection-status');
    if (!cs) return;
    cs.textContent = '\xB7 reconnecting';
    cs.className = '';
  };
  es.addEventListener('connected', function () {
    var cs = document.getElementById('connection-status');
    if (!cs) return;
    cs.textContent = '\xB7 LIVE';
    cs.className = 'live';
  });
})();
</script>`;
  assert25(html.length > 0, "injectSseScript: html must not be empty");
  return html;
}
function injectPanelScript() {
  const html = `<script>
(function () {
  document.querySelectorAll('[data-record-type]').forEach(function (row) {
    row.addEventListener('click', function () {
      var type = row.getAttribute('data-record-type');
      var file = row.getAttribute('data-record-file');
      if (!type || !file) return;
      var spinner = document.getElementById('panel-spinner');
      var body = document.getElementById('panel-body');
      var panel = document.getElementById('panel');
      var closeBtn = document.getElementById('panel-close');
      if (!panel || !body) return;
      if (spinner) { spinner.className = 'visible'; }
      body.style.display = 'none';
      panel.classList.add('open');
      document.body.classList.add('panel-open');
      if (closeBtn) { closeBtn.focus(); }
      fetch('/dashboard/record?type=' + encodeURIComponent(type) + '&file=' + encodeURIComponent(file))
        .then(function (r) {
          if (!r.ok) { return Promise.reject(r.status); }
          return r.text();
        })
        .then(function (text) {
          if (spinner) { spinner.className = ''; }
          body.style.display = '';
          var pre = document.createElement('pre');
          pre.style.cssText = 'white-space:pre-wrap;font-family:\\'JetBrains Mono\\',monospace;font-size:12px;color:#f0f0f0;line-height:1.5';
          pre.textContent = text;
          body.innerHTML = '';
          body.appendChild(pre);
        })
        .catch(function (status) {
          if (spinner) { spinner.className = ''; }
          body.style.display = '';
          body.textContent = status === 404 ? 'Record not found.' : 'Could not load record. Check your connection and try again.';
        });
    });
  });
})();
</script>`;
  assert25(html.length > 0, "injectPanelScript: html must not be empty");
  return html;
}
function esc2(s2) {
  return s2.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}
function clamp(n2, min, max) {
  return Math.max(min, Math.min(max, n2));
}
function arcGauge(pct, color, label, id) {
  const r2 = 52;
  const cx = 70;
  const cy = 70;
  const startAngle = -210;
  const sweepAngle = 240;
  function polar(deg, radius) {
    const rad = deg * Math.PI / 180;
    return { x: cx + radius * Math.cos(rad), y: cy + radius * Math.sin(rad) };
  }
  function arc(from, to, radius) {
    const s2 = polar(from, radius);
    const e2 = polar(to, radius);
    const large = to - from > 180 ? 1 : 0;
    return `M ${s2.x.toFixed(2)} ${s2.y.toFixed(2)} A ${radius} ${radius} 0 ${large} 1 ${e2.x.toFixed(2)} ${e2.y.toFixed(2)}`;
  }
  const trackEnd = startAngle + sweepAngle;
  const arcLen = sweepAngle / 360 * 2 * Math.PI * r2;
  return `<svg id="${id}" viewBox="0 0 140 120" xmlns="http://www.w3.org/2000/svg" style="width:140px;height:120px" data-pct="${clamp(pct, 0, 100)}" data-color="${color}" data-arclen="${arcLen.toFixed(2)}">
    <path d="${arc(startAngle, trackEnd, r2)}" fill="none" stroke="#2a2a2a" stroke-width="10" stroke-linecap="round"/>
    <path class="gauge-fill" d="${arc(startAngle, trackEnd, r2)}" fill="none" stroke="${color}" stroke-width="10" stroke-linecap="round" stroke-dasharray="0 ${arcLen.toFixed(2)}" style="transition:stroke-dasharray 1.2s cubic-bezier(.4,0,.2,1)"/>
    <text class="gauge-val" x="${cx}" y="${cy - 4}" text-anchor="middle" fill="white" font-family="'JetBrains Mono',monospace" font-size="20" font-weight="700">0%</text>
    <text x="${cx}" y="${cy + 16}" text-anchor="middle" fill="#666" font-family="'JetBrains Mono',monospace" font-size="9">${label}</text>
  </svg>`;
}
function sparkline(counts, color, id) {
  if (counts.length === 0)
    return `<svg viewBox="0 0 160 40" xmlns="http://www.w3.org/2000/svg" style="width:100%;max-width:160px;height:40px"><text x="80" y="24" text-anchor="middle" fill="#444" font-size="10">no data</text></svg>`;
  const values = counts.length === 1 ? [counts[0], counts[0]] : counts;
  const max = Math.max(...values);
  const min = Math.min(...values);
  const range = max - min || 1;
  const w2 = 160;
  const h2 = 40;
  const pad = 4;
  const pts = values.map((v2, i2) => {
    const x2 = pad + i2 / (values.length - 1) * (w2 - pad * 2);
    const y2 = max === min ? h2 / 2 : h2 - pad - (v2 - min) / range * (h2 - pad * 2);
    return `${x2.toFixed(1)},${y2.toFixed(1)}`;
  });
  const lastPt = pts[pts.length - 1].split(",");
  const pathLen = (w2 - pad * 2) * 1.2;
  return `<svg viewBox="0 0 ${w2} ${h2}" xmlns="http://www.w3.org/2000/svg" style="width:100%;max-width:${w2}px;height:${h2}px">
    <polyline id="${id}" points="${pts.join(" ")}" fill="none" stroke="${color}" stroke-width="2" stroke-linejoin="round" stroke-dasharray="${pathLen}" stroke-dashoffset="${pathLen}" style="transition:stroke-dashoffset 1.4s ease-out"/>
    <circle class="spark-dot" cx="${lastPt[0]}" cy="${lastPt[1]}" r="3" fill="${color}" opacity="0"/>
  </svg>`;
}
function sessionBarChart(items) {
  if (items.length === 0)
    return `<div style="color:#444;font-size:.75rem;font-style:italic;padding:.5rem 0">No sessions recorded</div>`;
  const groups = {};
  for (const item of items) {
    const key = item.date.slice(0, 7) || "unknown";
    groups[key] = (groups[key] ?? 0) + 1;
  }
  const entries = Object.entries(groups).sort(([a2], [b2]) => a2.localeCompare(b2)).slice(-8);
  const maxVal = Math.max(...entries.map(([, v2]) => v2), 1);
  const barH = 18;
  const gap = 5;
  const labelW = 64;
  const chartW = 220;
  const svgH = entries.length * (barH + gap) + 4;
  const bars = entries.map(([label, val], i2) => {
    const y2 = i2 * (barH + gap) + 2;
    const targetW = Math.max(4, val / maxVal * chartW);
    return `<text x="${labelW - 6}" y="${y2 + barH - 4}" text-anchor="end" fill="#666" font-family="'JetBrains Mono',monospace" font-size="9">${label}</text>
    <rect class="bar-rect" x="${labelW}" y="${y2}" width="0" height="${barH}" rx="2" fill="#00D2BE" opacity="0.85" data-w="${targetW.toFixed(1)}" style="transition:width .8s cubic-bezier(.4,0,.2,1)"/>
    <text class="bar-val" x="${labelW + 4}" y="${y2 + barH - 4}" fill="#00D2BE" font-family="'JetBrains Mono',monospace" font-size="9" opacity="0">${val}</text>`;
  }).join("\n    ");
  return `<svg id="bar-chart" viewBox="0 0 ${labelW + chartW + 32} ${svgH}" xmlns="http://www.w3.org/2000/svg" style="width:100%;max-width:${labelW + chartW + 32}px;height:${svgH}px">${bars}</svg>`;
}
function bucketByPeriod(items) {
  if (items.length === 0)
    return [];
  const groups = {};
  for (const item of items) {
    const key = item.date.slice(0, 7) || "unknown";
    groups[key] = (groups[key] ?? 0) + 1;
  }
  const counts = Object.entries(groups).sort(([a2], [b2]) => a2.localeCompare(b2)).map(([, v2]) => v2);
  assert25(counts.length >= 1, "bucketByPeriod: non-empty input must yield non-empty output");
  return counts;
}
